export type PublicSiteKey = 'MAIN' | 'PARTNER_RECRUITMENT';
export type PublicSitePageStatus = 'DRAFT' | 'PUBLISHED';
export type PublicSiteSectionKind =
  | 'HERO'
  | 'APP_OVERVIEW'
  | 'PARTNER_DIRECTORY'
  | 'PARTNER_DETAIL'
  | 'RECRUITMENT_BENEFITS'
  | 'RECRUITMENT_PROCESS'
  | 'COMPANY_INFORMATION'
  | 'CONTACT'
  | 'LEGAL_DOCUMENT'
  | 'FAQ'
  | 'CTA';

export type PublicSiteSection = {
  id: string;
  pageId: string;
  key: string;
  kind: PublicSiteSectionKind;
  content: Record<string, unknown>;
  sortOrder: number;
  enabled: boolean;
  updatedAt: string;
};

export type PublicSitePage = {
  id: string;
  site: PublicSiteKey;
  locale: string;
  path: string;
  internalName: string;
  status: PublicSitePageStatus;
  seoTitle?: string | null;
  seoDescription?: string | null;
  canonicalPath?: string | null;
  noIndex: boolean;
  publishedAt?: string | null;
  updatedAt: string;
  sections: PublicSiteSection[];
};

